export default Navbar;

import React, { useState, useEffect } from 'react';
import { useLocation } from 'react-router-dom';
import { Search, ShieldAlert, CheckCircle2, XCircle, Clock, AlertTriangle } from 'lucide-react';
import { MOCK_REGISTRY } from '../data/mockData';
import { RegistryEntry } from '../types';

const Registry: React.FC = () => {
  const location = useLocation();
  const [searchTerm, setSearchTerm] = useState('');
  const [results, setResults] = useState<RegistryEntry[]>(MOCK_REGISTRY);

  useEffect(() => {
    const params = new URLSearchParams(location.search);
    const q = params.get('q');
    if (q) {
      setSearchTerm(q);
      handleSearch(q);
    }
  }, [location.search]);

  const handleSearch = (term: string) => {
    const filtered = MOCK_REGISTRY.filter(entry => 
      entry.name.toLowerCase().includes(term.toLowerCase()) || 
      entry.id.toLowerCase().includes(term.toLowerCase())
    );
    setResults(filtered);
  };

  const getStatusStyle = (status: string) => {
    switch(status) {
      case 'Active': return 'bg-green/10 text-green-700 border-green/20';
      case 'Lapsed': return 'bg-amber/10 text-amber-700 border-amber/20';
      case 'Suspended': return 'bg-navy/10 text-navy/70 border-navy/20';
      case 'Revoked': return 'bg-red-100 text-red-700 border-red-200';
      default: return 'bg-gray-100 text-gray-700';
    }
  };

  const getStatusIcon = (status: string) => {
    switch(status) {
      case 'Active': return <CheckCircle2 className="h-4 w-4" />;
      case 'Lapsed': return <Clock className="h-4 w-4" />;
      case 'Suspended': return <ShieldAlert className="h-4 w-4" />;
      case 'Revoked': return <XCircle className="h-4 w-4" />;
      default: return null;
    }
  };

  return (
    <div className="bg-white min-h-screen py-12">
      <div className="max-w-5xl mx-auto px-4 sm:px-6 lg:px-8">
        <div className="text-center mb-12">
          <h1 className="text-4xl font-bold text-navy mb-4 italic">Public Credential Registry</h1>
          <p className="text-navy/60 max-w-2xl mx-auto">Verify the status and history of any individual holding a GCMWC credential. Status information is updated daily.</p>
        </div>

        <div className="bg-beige p-8 rounded shadow-inner mb-12">
          <div className="relative max-w-2xl mx-auto">
            <input 
              type="text" 
              value={searchTerm}
              onChange={(e) => {
                setSearchTerm(e.target.value);
                handleSearch(e.target.value);
              }}
              placeholder="Search by name or Credential ID (e.g., C-1001)..."
              className="w-full pl-12 pr-4 py-4 border-2 border-navy/10 focus:border-navy focus:outline-none bg-white rounded shadow-sm transition-all"
            />
            <Search className="absolute left-4 top-1/2 -translate-y-1/2 h-6 w-6 text-navy/40" />
          </div>
        </div>

        <div className="space-y-6">
          {results.length > 0 ? (
            results.map((entry) => (
              <div key={entry.id} className="border border-beige p-6 rounded shadow-sm hover:shadow-md transition-all bg-white relative overflow-hidden group">
                <div className={`absolute left-0 top-0 bottom-0 w-1.5 ${
                  entry.status === 'Active' ? 'bg-green' : entry.status === 'Revoked' ? 'bg-red-600' : 'bg-amber'
                }`}></div>

                <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
                  <div>
                    <div className="flex items-center space-x-3 mb-1">
                      <h3 className="text-xl font-bold text-navy">{entry.name}</h3>
                      <span className={`flex items-center space-x-1.5 px-3 py-1 border rounded-full text-xs font-bold uppercase ${getStatusStyle(entry.status)}`}>
                        {getStatusIcon(entry.status)}
                        <span>{entry.status}</span>
                      </span>
                    </div>
                    <p className="text-navy/50 text-sm font-mono tracking-tight">ID: {entry.id} | {entry.type === 'MWC-C' ? 'Certified Mental Wellness Coach' : 'Trained Mental Wellness Coach'}</p>
                  </div>

                  <div className="grid grid-cols-2 gap-8 text-xs font-bold uppercase tracking-widest text-navy/40">
                    <div>
                      <p className="mb-1">Issued</p>
                      <p className="text-navy/80">{new Date(entry.issueDate).toLocaleDateString()}</p>
                    </div>
                    <div>
                      <p className="mb-1">Expires</p>
                      <p className="text-navy/80">{new Date(entry.renewalDate).toLocaleDateString()}</p>
                    </div>
                  </div>
                </div>

                {entry.disciplinaryNote && (
                  <div className="mt-6 p-4 bg-amber/5 border border-amber/20 rounded flex items-start space-x-3">
                    <AlertTriangle className="h-5 w-5 text-amber shrink-0 mt-0.5" />
                    <div>
                      <p className="text-xs font-bold uppercase text-amber tracking-widest mb-1">Public Disciplinary Note</p>
                      <p className="text-sm text-navy/70 italic leading-relaxed">{entry.disciplinaryNote}</p>
                    </div>
                  </div>
                )}
              </div>
            ))
          ) : (
            <div className="text-center py-20 bg-beige/20 border-2 border-dashed border-beige">
              <p className="text-navy/40 font-bold uppercase tracking-widest">No matching credentials found.</p>
            </div>
          )}
        </div>

        <div className="mt-16 bg-navy text-white p-8">
          <h4 className="font-bold text-lg mb-4 uppercase tracking-widest">About Verification Results</h4>
          <div className="grid md:grid-cols-2 gap-8 text-sm opacity-80 leading-relaxed">
            <p>
              <strong>Active:</strong> The individual is in good standing and holds a valid credential. 
              They are authorized for the scope of practice associated with their specific tier.
            </p>
            <p>
              <strong>Revoked:</strong> The individual's credential has been permanently removed due to serious ethical or professional violations. 
              They are not authorized to use any GCMWC titles or designations.
            </p>
          </div>
        </div>
      </div>
    </div>
  );
};

export default Registry;

import React, { useState } from 'react';
import { Link } from 'react-router-dom';
import { Filter, Search, MapPin, Globe, ExternalLink, AlertCircle, ToggleLeft, ToggleRight } from 'lucide-react';
import { MOCK_DIRECTORY } from '../data/mockData';
import { DirectoryEntry } from '../types';

const Directory: React.FC = () => {
  const [includeMWCT, setIncludeMWCT] = useState(false);
  const [locationFilter, setLocationFilter] = useState('');

  const filtered = MOCK_DIRECTORY.filter(entry => {
    const statusMatch = entry.status === 'Active';
    const typeMatch = includeMWCT ? true : entry.type === 'MWC-C';
    const locMatch = entry.location.toLowerCase().includes(locationFilter.toLowerCase());
    return statusMatch && typeMatch && locMatch;
  });

  return (
    <div className="bg-white min-h-screen">
      <div className="bg-navy text-white py-12">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
          <h1 className="text-4xl font-bold mb-4 italic tracking-tight uppercase">Referral Directory</h1>
          <p className="text-teal/80 max-w-2xl font-medium">Find professional support from Active GCMWC Certified Coaches. Verified standards for non-clinical mental wellness.</p>
        </div>
      </div>

      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-10">
        {includeMWCT && (
          <div className="mb-8 p-4 bg-amber/10 border-l-4 border-amber flex items-start space-x-4">
            <AlertCircle className="h-6 w-6 text-amber shrink-0 mt-0.5" />
            <p className="text-sm font-medium text-navy leading-relaxed">
              MWC-T is a training designation for supervised, educational, or volunteer contexts. 
              For independent professional readiness, search MWC-C.
            </p>
          </div>
        )}

        <div className="flex flex-col lg:flex-row gap-8">
          {/* Filters Sidebar */}
          <aside className="w-full lg:w-1/4 space-y-8">
            <div className="bg-beige p-6">
              <h3 className="text-xs font-bold uppercase tracking-[0.2em] text-navy mb-6 border-b border-navy/10 pb-2 flex items-center">
                <Filter className="h-3 w-3 mr-2" /> Filters
              </h3>

              <div className="space-y-6">
                <div>
                  <label className="block text-[10px] font-bold uppercase tracking-widest text-navy/40 mb-2">Include Training Status</label>
                  <button 
                    onClick={() => setIncludeMWCT(!includeMWCT)}
                    className="flex items-center space-x-2 text-navy hover:text-teal transition-colors"
                  >
                    {includeMWCT ? <ToggleRight className="h-6 w-6 text-teal" /> : <ToggleLeft className="h-6 w-6" />}
                    <span className="text-sm font-semibold uppercase tracking-wider">Show MWC-T</span>
                  </button>
                </div>

                <div>
                  <label className="block text-[10px] font-bold uppercase tracking-widest text-navy/40 mb-2">Location</label>
                  <div className="relative">
                    <input 
                      type="text" 
                      value={locationFilter}
                      onChange={(e) => setLocationFilter(e.target.value)}
                      placeholder="City or Region"
                      className="w-full pl-9 pr-4 py-2 text-sm border border-navy/10 bg-white"
                    />
                    <MapPin className="absolute left-2.5 top-1/2 -translate-y-1/2 h-4 w-4 text-navy/30" />
                  </div>
                </div>

                <div>
                  <label className="block text-[10px] font-bold uppercase tracking-widest text-navy/40 mb-2">Practice Model</label>
                  <div className="space-y-2">
                    <label className="flex items-center space-x-2 text-xs font-bold text-navy/70 uppercase tracking-wider">
                      <input type="checkbox" className="accent-teal" defaultChecked /> <span>Remote Only</span>
                    </label>
                    <label className="flex items-center space-x-2 text-xs font-bold text-navy/70 uppercase tracking-wider">
                      <input type="checkbox" className="accent-teal" /> <span>In-Person</span>
                    </label>
                  </div>
                </div>
              </div>
            </div>
          </aside>

          {/* Results Grid */}
          <main className="w-full lg:w-3/4">
            <div className="mb-6 flex justify-between items-center text-[10px] font-bold uppercase tracking-[0.2em] text-navy/40">
              <span>{filtered.length} Result{filtered.length !== 1 ? 's' : ''}</span>
              <span>Showing: {includeMWCT ? 'MWC-C + MWC-T' : 'MWC-C Only'}</span>
            </div>

            <div className="grid sm:grid-cols-2 gap-6">
              {filtered.map((entry) => (
                <div key={entry.id} className="bg-white border border-beige p-6 shadow-sm hover:shadow-md transition-shadow group flex flex-col h-full">
                  <div className="flex justify-between items-start mb-4">
                    <div>
                      <h4 className="text-lg font-bold text-navy mb-1">{entry.name}</h4>
                      <span className={`inline-block px-2 py-0.5 rounded-full text-[9px] font-bold uppercase tracking-wider ${
                        entry.type === 'MWC-C' ? 'bg-teal/10 text-teal-800' : 'bg-amber/10 text-amber-800'
                      }`}>
                        {entry.type}
                      </span>
                    </div>
                    <Link 
                      to={`/registry?q=${entry.id}`} 
                      className="text-navy/40 hover:text-teal transition-colors"
                      title="Verify Credential"
                    >
                      <ExternalLink className="h-4 w-4" />
                    </Link>
                  </div>

                  <div className="space-y-3 mb-6 flex-grow">
                    <div className="flex items-center text-xs text-navy/60 font-semibold uppercase tracking-wider">
                      <MapPin className="h-3 w-3 mr-2" /> {entry.location}
                    </div>
                    <div className="flex items-center text-xs text-navy/60 font-semibold uppercase tracking-wider">
                      <Globe className="h-3 w-3 mr-2" /> {entry.language.join(', ')}
                    </div>
                    <div className="flex flex-wrap gap-1.5 mt-2">
                      {entry.focusAreas.map(area => (
                        <span key={area} className="text-[9px] bg-beige px-2 py-0.5 text-navy/70 font-bold uppercase tracking-wider">{area}</span>
                      ))}
                    </div>
                  </div>

                  <div className="pt-4 border-t border-beige flex justify-between items-center">
                    <div className="flex space-x-2">
                      {entry.remote && <span className="text-[9px] font-bold text-navy/40 uppercase">Remote</span>}
                      {entry.inPerson && <span className="text-[9px] font-bold text-navy/40 uppercase">In-Person</span>}
                    </div>
                    <Link 
                      to={`/contact?coach=${entry.id}`}
                      className="text-[10px] font-bold uppercase tracking-widest text-teal hover:text-navy transition-colors"
                    >
                      Contact Coach
                    </Link>
                  </div>
                </div>
              ))}
            </div>

            {filtered.length === 0 && (
              <div className="py-20 text-center border-2 border-dashed border-beige">
                <p className="text-navy/40 font-bold uppercase tracking-widest">No active coaches matching your criteria.</p>
              </div>
            )}
          </main>
        </div>
      </div>
    </div>
  );
};

export default Directory;

